abstract class KitchenTool{private int speedLevel=1;abstract String prepare();int getSpeedLevel(){return speedLevel;}void setSpeedLevel(int s){if(s<1||s>5)throw new IllegalArgumentException();speedLevel=s;}}interface Washable{String clean();}class Blender extends KitchenTool implements Washable{String prepare(){return "Blending at speed "+getSpeedLevel();}public String clean(){return "Blender rinsed and dried";}}public class Main{public static void main(String[]a){}}